import React, { useEffect, useState } from "react";
import "./BuyHouseList.css"; // reuse same styles

function formatCurrencyINR(n) {
  if (n == null || isNaN(n)) return "₹0.00";
  const v = Number(n);
  if (v <= 0) return "₹0.00";
  if (v >= 1e7) return `₹${(v / 1e7).toFixed(2)} Cr`;
  if (v >= 1e5) return `₹${(v / 1e5).toFixed(2)} L`;
  return `₹${v.toLocaleString("en-IN")}`;
}

export default function BuyLandList() {
  const [lands, setLands] = useState([]);
  const [loading, setLoading] = useState(true);
  const [err, setErr] = useState("");
  const [revealed, setRevealed] = useState({});
  const [predicted, setPredicted] = useState({});
  const [predicting, setPredicting] = useState({});
  const [lightboxSrc, setLightboxSrc] = useState(null);

  const openLightbox = (src) => setLightboxSrc(src);
  const closeLightbox = () => setLightboxSrc(null);

  useEffect(() => {
    const load = async () => {
      setLoading(true);
      setErr("");
      try {
        const res = await fetch(`${process.env.REACT_APP_BACKEND_URL}/buy/lands`);
        if (!res.ok) throw new Error(`HTTP ${res.status}`);
        const data = await res.json();
        setLands(Array.isArray(data) ? data : []);
      } catch (e) {
        setErr("Unable to fetch land listings. Please try again.");
      } finally {
        setLoading(false);
      }
    };
    load();
  }, []);

  useEffect(() => {
    const onKey = (e) => { if (e.key === "Escape") closeLightbox(); };
    if (lightboxSrc) window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [lightboxSrc]);

  const num = (x, def = 0) => {
    const v = Number(x);
    return Number.isFinite(v) ? v : def;
  };

  async function doPredict(land) {
    // Allow future support for cents/acres; backend will derive
    const payload = {
      Area_sqft: num(land.area_sqft, 0),
      zoning: land.zoning || "Residential",
      latitude: num(land.latitude, 0),
      longitude: num(land.longitude, 0),

      // Optional: pass cents or area (acres) if you add them to cards later
      // cents: num(land.cents, 0),
      // area: num(land.area, 0),

      // Amenities; default to notApplicable unless you stored distances
      waterApplicable: land.waterApplicable || "notApplicable",
      waterDistance: num(land.waterDistance, 0),
      roadApplicable: land.roadApplicable || "notApplicable",
      roadDistance: num(land.roadDistance, 0),
      schoolApplicable: land.schoolApplicable || "notApplicable",
      schoolDistance: num(land.schoolDistance, 0),
      railwayApplicable: land.railwayApplicable || "notApplicable",
      railwayDistance: num(land.railwayDistance, 0),
      busApplicable: land.busApplicable || "notApplicable",
      busDistance: num(land.busDistance, 0),

      // Help backend keep result "near" listing price
      askingPrice: num(land.actualPrice, 0)
    };

    setPredicting((p) => ({ ...p, [land.id]: true }));
    try {
      const res = await fetch(`${process.env.REACT_APP_LAND_API || process.env.REACT_APP_BACKEND_URL}/predict/land`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(payload)
      });
      if (!res.ok) {
        const text = await res.text();
        throw new Error(text || `HTTP ${res.status}`);
      }
      const data = await res.json();
      setPredicted((p) => ({ ...p, [land.id]: data })); // store full object
    } catch (e) {
      console.error("Land predict error:", e);
      setPredicted((p) => ({ ...p, [land.id]: null }));
      alert(`Prediction failed: ${e?.message || e}`);
    } finally {
      setPredicting((p) => ({ ...p, [land.id]: false }));
    }
  }

  if (loading) return <div className="buy-loading">Loading land listings...</div>;
  if (err) return <div className="buy-error">{err}</div>;
  if (!lands.length) return <div className="buy-empty">No land listings found.</div>;

  return (
    <div className="buy-root">
      {lands.map((l) => {
        const isRevealed = revealed[l.id];
        const predObj = predicted[l.id];
        const pred = predObj?.price;
        const actual = l.actualPrice != null ? Number(l.actualPrice) : 0;
        const showDeal = typeof pred === "number" && actual > 0 && pred < actual;

        const areaSqft = num(l.area_sqft, 0);

        return (
          <div className="buy-card" key={l.id}>
            <div className="buy-card-left">
              <div className="buy-thumb">
                {l.image ? (
                  <button
                    type="button"
                    className="thumb-click"
                    onClick={() =>
                      openLightbox(`${process.env.REACT_APP_BACKEND_URL}${l.image}`)
                    }
                    aria-label="View full image"
                  >
                    <img
                      src={`${process.env.REACT_APP_BACKEND_URL}${l.image}`}
                      alt=""
                    />
                  </button>
                ) : (
                  <div className="no-img">No Image</div>
                )}
                <span className="badge">Land</span>
              </div>
            </div>

            <div className="buy-card-mid">
              <div className="buy-title">
                {l.zoning || "Land"} in {l.city || l.district || l.state || l.location || ""}
              </div>

              <div className="buy-meta">
                <div className="price">{formatCurrencyINR(actual)}</div>
                <div className="meta-item">
                  {areaSqft > 0 ? `${areaSqft.toLocaleString()} sq.ft` : "—"}
                </div>
                {l.zoning && <div className="meta-item">{l.zoning}</div>}
              </div>

              {typeof pred === "number" && (
                <div className={`predict-row ${showDeal ? "deal-ok" : "deal-warn"}`}>
                  <span>Model price: {formatCurrencyINR(pred)}</span>
                  {showDeal ? (
                    <span className="deal good">Good deal</span>
                  ) : (
                    <span className="deal warn">Above model</span>
                  )}
                  <div className="sub">
                    <span>
                      ₹/sqft:{" "}
                      {predObj?.price_per_sqft != null
                        ? `₹${Number(predObj.price_per_sqft).toLocaleString("en-IN")}`
                        : "N/A"}
                    </span>
                    <span style={{ marginLeft: 8 }}>
                      ₹/cent:{" "}
                      {predObj?.price_per_cent != null
                        ? `₹${Number(predObj.price_per_cent).toLocaleString("en-IN")}`
                        : "N/A"}
                    </span>
                  </div>
                </div>
              )}

              {(l.location || l.city || l.district || l.state) && (
                <div className="location-row">
                  <span className="pin">📍</span>
                  <span className="loc-text">
                    {l.location || [l.city, l.district, l.state].filter(Boolean).join(", ")}
                  </span>
                </div>
              )}
            </div>

            <div className="buy-card-right">
              <div className="btn-row">
                <button
                  className="btn contact"
                  onClick={() =>
                    setRevealed((r) => ({ ...r, [l.id]: !isRevealed }))
                  }
                >
                  {isRevealed ? l.contact || "NA" : "Contact"}
                </button>

                <button
                  className="btn predict"
                  disabled={predicting[l.id]}
                  onClick={() => doPredict(l)}
                >
                  {predicting[l.id] ? "Predicting..." : "Predict"}
                </button>
              </div>
            </div>
          </div>
        );
      })}

      {lightboxSrc && (
        <div
          className="lb-overlay"
          onClick={closeLightbox}
          role="dialog"
          aria-modal="true"
        >
          <div className="lb-content" onClick={(e) => e.stopPropagation()}>
            <button className="lb-close" onClick={closeLightbox} aria-label="Close">
              ×
            </button>
            <img src={lightboxSrc} alt="" />
          </div>
        </div>
      )}
    </div>
  );
}
